    \begin{tikzpicture}[scale=1.2, transform shape]

      \node[anchor=north east] at (-0.10,0) {$s$};

      \draw[fill=white, line width=1pt] (0,0) circle[radius=4.25pt];

      \foreach \angle/\index in {
        135/i,
         85/j,
         35/{\ldots},
        -15/k
      }{
        \draw[line width=0.6pt]
          (\angle:4.25pt) -- (\angle:0.70cm);
      }
      \draw[fill=white, line width=0.85pt] (35:0.4cm) circle[radius=3pt];
      \node[font=\scriptsize, anchor=south] at (35:0.4cm) {$1$};
    \end{tikzpicture}
  }} =& \vcenter{\hbox{
    \begin{tikzpicture}[scale=1.2, transform shape]

      \node[anchor=north east, font=\small] at (-0.10,0) {$s+1$};

      \draw[fill=white, line width=1pt] (0,0) circle[radius=4.25pt];

      \foreach \angle/\index in {
        135/i,
         85/j,
         35/{\ldots},
        -15/k
      }{
