\begin{proposition}[Noisy constant-depth logical operations]
Suppose a logical operation is implemented by an ideal circuit
\begin{equation}
G=G_D\cdots G_1,
\qquad
G_t=\prod_{\alpha\in A_t}g_{t,\alpha},
\label{eq:ideal-logical-circuit}
\end{equation}
where \(D=O(1)\) and all physical gates have support size at most \(r=O(1)\),
with pairwise-disjoint supports within each layer. Let
\(\widetilde g_{t,\alpha}\) denote the corresponding noisy unitary physical gate
and $\widetilde G$ be the noisy circuit.
Then every noisy physical gate admits a decomposition
\begin{equation}
\begin{aligned}
&\widetilde g_{t,\alpha}
=u_{t,\alpha}g_{t,\alpha},
\qquad
u_{t,\alpha}=e^{-\mathrm i\eta h_{t,\alpha}}, \qquad h_{t,\alpha}=h_{t,\alpha}^\dagger,
\end{aligned}
\label{eq:gate-noise-decomposition}
\end{equation}
with $\norm{h_{t,\alpha}}\le1$ and for a common \(\eta\ge0\). After propagating all \(u_{t,\alpha}\) through the
remaining ideal gates, the noisy implementation can be written as
\begin{equation}
\widetilde G=UG,
\label{eq:propagated-noisy-logical-circuit}
\end{equation}
where \(U\) is a local coherent error in
Eq.~\eqref{eq:app-circuit}, with depth at most $D r^{2D-1}$ and support bound at most $r^D$.
\end{proposition}

\begin{proof}
The settings are illustrated in Fig.~\ref{fig:local-coherent-error}. Define
\begin{equation}
v_{t,\alpha}
\coloneqq \widetilde g_{t,\alpha}g_{t,\alpha}^\dagger.
\label{eq:relative-unitary-error}
\end{equation}
Since \(v_{t,\alpha}\) is unitary, there exists a Hermitian operator
\(K_{t,\alpha}\) on the same physical-gate support such that
\begin{equation}
v_{t,\alpha}
=e^{-\mathrm iK_{t,\alpha}},
\qquad
\norm{K_{t,\alpha}}\le\pi.
\label{eq:relative-error-logarithm}
\end{equation}
Set
\begin{equation}
\eta\coloneqq \max_{t,\alpha}\norm{K_{t,\alpha}},
\qquad
h_{t,\alpha}\coloneqq 
\begin{cases}
K_{t,\alpha}/\eta, & \eta>0,\\
0, & \eta=0.
\end{cases}
\label{eq:common-noise-strength}
\end{equation}
Then
\begin{equation}
\widetilde g_{t,\alpha}
=e^{-\mathrm i\eta h_{t,\alpha}}g_{t,\alpha},
\qquad
\norm{h_{t,\alpha}}\le1,
\label{eq:gate-error-factorization}
\end{equation}
which proves Eq.~\eqref{eq:gate-noise-decomposition}.

Because the supports within each layer are pairwise disjoint,
\begin{equation}
\widetilde G_t=U_tG_t,
\qquad
U_t\coloneqq \prod_{\alpha\in A_t}u_{t,\alpha}.
\label{eq:noisy-layer-decomposition}
\end{equation}
Define
\begin{equation}
S_t\coloneqq G_D\cdots G_{t+1},
\qquad
S_D\coloneqq I.
\label{eq:remaining-ideal-circuit}
\end{equation}
Successively moving the ideal gates to the right gives
\begin{equation}
\widetilde G
=\left(\prod_{t=D}^{1}S_tU_tS_t^\dagger\right)G,
\label{eq:propagation-identity}
\end{equation}
where the product is ordered with decreasing \(t\). For every \(t\),
\begin{equation}
S_tU_tS_t^\dagger
=\prod_{\alpha\in A_t}e^{-\mathrm i\eta h'_{t,\alpha}},
\qquad
h'_{t,\alpha}\coloneqq  S_th_{t,\alpha}S_t^\dagger,
\label{eq:propagated-generators}
\end{equation}
and unitary conjugation gives
\begin{equation}
\norm{h'_{t,\alpha}}
=\norm{h_{t,\alpha}}
\le1.
\label{eq:propagated-generator-norm}
\end{equation}

Conjugation through one layer of pairwise-disjoint \(r\)-supported gates maps an
operator supported on \(q\) qubits to one supported on at most \(rq\) qubits.
Therefore
\begin{equation}
\bigl|\supp(h'_{t,\alpha})\bigr|
\le r^{D-t+1}
\le r^D.
\label{eq:propagated-support-bound}
\end{equation}
For fixed \(t\), the original \(u_{t,\alpha}\) commute, hence
\begin{equation}
\left[
S_tu_{t,\alpha}S_t^\dagger,
S_tu_{t,\beta}S_t^\dagger
\right]=0
\qquad
(\alpha,\beta\in A_t).
\label{eq:propagated-errors-commute}
\end{equation}
Let \(k=D-t\). A backward light cone through \(k\) layers contains at most
\(r^k\) qubits. Since the original supports in \(A_t\) are pairwise disjoint,
the number of propagated supports from \(A_t\) intersecting a certain propagated
support is at most
\begin{equation}
r^{k+1}r^k=r^{2k+1}\le r^{2D-1}.
\label{eq:propagated-overlap-bound}
\end{equation}
Hence their intersection graph has maximum degree at most
\(r^{2D-1}-1\) and can be colored with at most \(r^{2D-1}\) colors. By Eq.~\eqref{eq:propagated-errors-commute}, the color classes may be
used as sublayers without changing the product. Applying this independently
to the \(D\) original layers gives a circuit representation of \(U\) with depth at
most
\begin{equation}
Dr^{2D-1}=O(1)
\label{eq:effective-noise-depth}
\end{equation}
and support size at most
\begin{equation}
r^D=O(1).
\label{eq:effective-noise-support}
\end{equation}
Thus \(U\) satisfies the conditions of Eq.~\eqref{eq:app-circuit}.
\end{proof}}

To expand the noise channel into local {error} contributions,
let \(\Lambda\) denote the set of gate locations in \(U\),
and let \(u_\alpha\) be the unitary at location \(\alpha\).
Define
\begin{equation}
F_\alpha\coloneqq \Ad_{u_\alpha}-\id.
\label{eq:app-error-map}
\end{equation}
For \(B\subseteq\Lambda\), let \(F_B\) be the composition
of the maps \(F_\alpha\), \(\alpha\in B\), in the order
in which the corresponding gates act in \(U\), with
\(F_\varnothing=\id\).
Expanding each local channel as
\(\Ad_{u_\alpha}=\id+F_\alpha\) gives
\[
\Ad_U=\sum_{B\subseteq\Lambda}F_B.
\]

After the coherent error, the stabilizer generators are
measured. Let \(\{\Pi_s:s\in\Sigma\}\) be their nonzero
joint eigenspace projectors. They satisfy
\begin{equation}
\Pi_s\Pi_t=\delta_{st}\Pi_s,
\qquad
\sum_{s\in\Sigma}\Pi_s=I_P.
\label{eq:app-syndrome-projectors}
\end{equation}
The measurement channel outputs the syndrome in a register
\(S\), together with the postmeasurement physical state:
\begin{equation}
\cM(Y)
=
\sum_{s\in\Sigma}
\ket{s}\!\bra{s}_S\otimes\Pi_sY\Pi_s.
\label{eq:app-retained-measurement}
\end{equation}
Combining encoding, noise, and measurement gives
\begin{equation}
\cN_U\coloneqq \cN_{n,U,\eta}
=
\cM\circ\Ad_U\circ\cE.
\label{eq:app-noisy-channel}
\end{equation}

\section{Optimal recovery threshold}
\label{app:optimal}
In this section, we establish the coherent error threshold for the optimal recovery setting.
The \emph{optimal recovery logical error} is defined by
\begin{equation}
\eps_n^\star(U,\eta)
=
\inf_{\cR }
\frac12
\norm{\cR\circ\cN_U-\id_A}_\diamond,
\label{eq:app-optimal-error}
\end{equation}
where the infimum is over completely positive
trace-preserving (CPTP) maps from \(S\otimes P\) to \(A\).
The recovery is optimized separately for each circuit \(U_n(\eta)\).

\subsection{Logical information leakage and optimal recovery}
\label{app:syndrome-recovery}

In this section, we use the dependence of the syndrome distribution on the logical
input to quantify information leakage and bound the optimal recovery error.


For each \(s\in\Sigma\), define
\[
K_s\coloneqq \Pi_sUV.
\]
The postmeasurement channel in Eq.~\eqref{eq:app-noisy-channel} can then
be written as
\begin{equation}
\cN_U(X)
=
\sum_{s\in\Sigma}
\ket{s}\!\bra{s}_S\otimes K_sXK_s^\dagger .
\label{eq:appendix-postmeasurement-channel}
\end{equation}

Let \(E\) be a Hilbert space with orthonormal basis
\(\{\ket{s}_E:s\in\Sigma\}\), and define
\begin{equation}
W:A\rightarrow S\otimes P\otimes E,
\quad
W
=
\sum_{s\in\Sigma}
\ket{s}_S\otimes K_s\otimes\ket{s}_E .
\label{eq:appendix-W}
\end{equation}
We have
\begin{align}
W^\dagger W
&=
\sum_{s\in\Sigma}K_s^\dagger K_s
\nonumber\\
&=
V^\dagger U^\dagger
\left(\sum_{s\in\Sigma}\Pi_s\right)
UV
=
I_A .
\label{eq:W-isometry}
\end{align}

Hence \(W\) is an isometry. For any operator \(X\) on \(A\),
\begin{equation}
WXW^\dagger=\sum_{s,t\in\Sigma}
\ket{s}\!\bra{t}_S
\otimes K_sXK_t^\dagger
\otimes \ket{s}\!\bra{t}_E.
\end{equation}
Tracing out \(E\) therefore gives
\begin{equation}
\Tr_E\!\left(WXW^\dagger\right)
=
\sum_{s\in\Sigma}
\ket{s}\!\bra{s}_S\otimes K_sXK_s^\dagger
=
\cN_U(X).
\label{eq:appendix-stinespring}
\end{equation}
Thus \(W\) is a Stinespring isometry for \(\cN_U\), with output
system \(S\otimes P\) and environment \(E\).

A complementary channel corresponding to \(W\) is
\begin{align}
\cQ_U(X)
&\coloneqq 
\Tr_{SP}\!\left(WXW^\dagger\right)
\nonumber\\
&=
\sum_{s\in\Sigma}
\Tr\!\left(K_sXK_s^\dagger\right)
\ket{s}\!\bra{s}_E
\nonumber\\
&=
\sum_{s\in\Sigma}
\Tr\!\left(K_s^\dagger K_sX\right)
\ket{s}\!\bra{s}_E .
\label{eq:appendix-complement}
\end{align}
For every logical state \(\rho\), the diagonal entries of
\(\cQ_U(\rho)\) are precisely the probabilities of the syndrome
outcomes. We now compare these probabilities for different logical
inputs.

Let
\begin{equation}
\tau_A\coloneqq \frac{I_A}{\dim A},
\qquad
\cD_A(X)\coloneqq \Tr(X)\tau_A,
\label{eq:logical-depolarizing-channel}
\end{equation}
where \(\cD_A\) is the completely depolarizing channel on \(A\).
For every logical state \(\rho\),
\begin{equation}
\bigl[\cQ_U\circ(\id-\cD_A)\bigr](\rho)
=
\cQ_U(\rho)-\cQ_U(\tau_A).
\label{eq:syndrome-input-dependence}
\end{equation}
Thus the syndrome distribution is independent of the logical input
exactly when
\begin{equation}
\cQ_U\circ(\id-\cD_A)=0.
\label{eq:syndrome-independence}
\end{equation}
More generally,
\(\norm{\cQ_U\circ(\id-\cD_A)}_\diamond\)
measures {the information leakage to the environment, and equivalently} the dependency of input logical states.

The {error} expansion of \(\cQ_U\) contains terms that are independent
of the logical input. The following elementary observation gives a
convenient characterization of such terms.

\begin{lemma}
\label{lem:input-independence}
Let \(L\) be a linear map with input system \(A\). Then
\begin{equation}
L\circ(\id-\cD_A)=0
\quad\Longleftrightarrow\quad
L(X)=\Tr(X)L(\tau_A)
\label{eq:input-independent-characterization}
\end{equation}
for every operator \(X\) on \(A\).
Moreover, this equality remains valid in the presence of an arbitrary
reference system: for every finite-dimensional \(R\),
\begin{equation}
(L\otimes\id_R)
\circ
\bigl[(\id-\cD_A)\otimes\id_R\bigr]
=
0.
\label{eq:input-independent-cancellation}
\end{equation}
\end{lemma}

\begin{proof}
The first condition is equivalent to \(L=L\circ\cD_A\). Hence
\begin{equation}
L(X)
=
L\bigl(\Tr(X)\tau_A\bigr)
=
\Tr(X)L(\tau_A).    
\end{equation}

The converse follows from the same calculation. The last statement
follows by tensoring the equality
\(L\circ(\id-\cD_A)=0\) with \(\id_R\).
\end{proof}

We now relate this measure of syndrome dependence to the optimal
recovery error.

\begin{lemma}
\label{lem:recovery-from-syndrome}
The optimal recovery error of \(\cN_U\) satisfies
\begin{equation}
\epsilon^\star(\cN_U)
\leq
\sqrt{
\norm{\cQ_U\circ(\id-\cD_A)}_\diamond
}.
\label{eq:recovery-from-syndrome}
\end{equation}
\end{lemma}

\begin{proof}
Since \(\cQ_U\) is a complementary channel of \(\cN_U\) and
\(\cQ_U\circ\cD_A\) is a constant channel, {applying Theorem~3 of Ref. \cite{KretschmannSchlingemannWerner2008} in  Schr\"odinger picture \cite[Theorem~3]{HaydenWinter2012}} gives
\begin{equation}
\frac{1}{4}
\left(
\inf_{\cR}
\norm{\cR\circ\cN_U-\id_A}_\diamond
\right)^2
\leq
\norm{\cQ_U-\cQ_U\circ\cD_A}_\diamond.    
\end{equation}
The right-hand side is
\(
\norm{\cQ_U\circ(\id-\cD_A)}_\diamond,
\)
while the left-hand side is
\(\epsilon^\star(\cN_U)^2\) by definition. Taking the square root
proves Eq.~\eqref{eq:recovery-from-syndrome}.
\end{proof}

It remains to bound
\(\norm{\cQ_U\circ(\id-\cD_A)}_\diamond\).
In the next appendix, we show that a {error} contribution \(L_B\)
satisfies
\begin{equation}
    L_B(X)=\Tr(X)\sigma_B
\end{equation}
whenever every connected component of its physical support contains
fewer than \(d\) qubits. Here \(\sigma_B\) may depend on \(B\), but
not on \(X\). Lemma~\ref{lem:input-independence} then gives
\begin{equation}
L_B\circ(\id-\cD_A)=0.    
\end{equation}
Consequently, only {error} configurations containing a connected
component of size at least \(d\) need to be bounded.



\subsection{Error clusters and logical leakage}
\label{app:subdistance-cancellation}

This appendix shows that {error} configurations consisting only of
small connected components do not contribute to the dependence of
the syndrome distribution on the logical input. We first relate
connected components in the interaction graph to connected components
of their physical support. We then use the code distance to show that
the corresponding syndrome contributions are independent of the
logical input. 

The local coherent noise is defined by a depth-\(D\)
circuit
\[
U=U_D\cdots U_1,
\qquad
U_t=\prod_{a\in\mathcal A_t}e^{-i\eta h_{t,a}},
\]
where \(\mathcal A_t\) indexes the local unitary in layer
\(t\). Each \(h_{t,a}\) is supported on at most \(r\) physical
qubits, and the supports are pairwise disjoint within each layer.

We call the pair \(\alpha=(t,a)\), which identifies one local
unitary in the circuit, a location. The set of
locations is
\begin{equation}
\Lambda
\coloneqq 
\bigl\{(t,a):1\leq t\leq D,\ a\in\mathcal A_t\bigr\}.
\end{equation}
For \(\alpha=(t,a)\in\Lambda\), write
\[
h_\alpha\coloneqq h_{t,a},
\qquad
u_\alpha\coloneqq e^{-i\eta h_\alpha},
\qquad
S_\alpha\coloneqq \supp(h_\alpha).
\]

We now compare connectivity among coherent error locations with connectivity of their physical support. The check connectivity graph \(\Gamma\) has the physical qubits as vertices. The interaction graph \(H\) has vertex set \(\Lambda\), with two locations adjacent whenever their supports have distance at most one in \(\Gamma\).

For \(B\subseteq\Lambda\), define its physical support by 
\[
S_B\coloneqq \bigcup_{\alpha\in B}S_\alpha.
\]
The induced graph \(H[B]\) describes
connectivity among the locations in \(B\), while
\(\Gamma[S_B]\) describes connectivity within their physical support.
The following lemma bounds the size and degree of the interaction graph and relates its connected components to the connected components of their physical support.

\begin{lemma}
\label{lem:layered-geometry}
The coherent error locations and their supports satisfy the following:
\begin{enumerate}
    \item The number of locations     \(|\Lambda|\leq Dn.\)

    \item The maximum degree of the interaction graph \(H\) is at most \(D(\kappa+1)r-1.\)

    \item If \(C\subseteq\Lambda\) is connected in \(H\), then
    \(|S_C|\leq r|C|.\)

    \item For every \(B\subseteq\Lambda\) and every connected component \(T\) of \(\Gamma[S_B]\), there is a connected component \(C\) of \(H[B]\) such that \(T\subseteq S_C\), \(|T|\leq |S_C|\leq r|C|\).
\end{enumerate}
\end{lemma}

\begin{proof}
Within each layer, the supports are nonempty and pairwise disjoint,
so there are at most \(n\) locations. Summing over the \(D\) layers
proves item 1.

Let \(N_\Gamma[S_\alpha]\) denote the closed neighborhood
of \(S_\alpha\) in \(\Gamma\). Since
\(\deg(\Gamma)\leq\kappa\) and \(|S_\alpha|\leq r\),
\begin{equation}
|N_\Gamma [S_\alpha]|
\leq
(\kappa+1)|S_\alpha|
\leq
(\kappa+1)r.    
\end{equation}
In any layer, at most \(|N_\Gamma[S_\alpha]|\) pairwise disjoint supports can intersect \(N_\Gamma[S_\alpha]\). Hence at most \(D(\kappa+1)r\) locations are equal or adjacent to \(\alpha\) in
\(H\), which proves item 2 after excluding \(\alpha\) itself.

Item 3 follows directly from
\begin{equation}
    |S_C|
=
\left|\bigcup_{\alpha\in C}S_\alpha\right|
\leq
\sum_{\alpha\in C}|S_\alpha|
\leq
r|C|.
\end{equation}

For item 4, let
\begin{equation}
I_T\coloneqq \{\alpha\in B:S_\alpha\cap T\neq\varnothing\}.    
\end{equation}
This set is connected in \(H[B]\). Indeed, for
\(\alpha,\beta\in I_T\), choose
\(x\in S_\alpha\cap T\) and \(y\in S_\beta\cap T\), and let
\[
x=v_0,v_1,\ldots,v_p=y
\]
be a path in \(T\). For each \(i\), choose
\(\gamma_i\in B\) such that \(v_i\in S_{\gamma_i}\), with
\(\gamma_0=\alpha\) and \(\gamma_p=\beta\). Consecutive locations
\(\gamma_i\) and \(\gamma_{i+1}\) are either equal or adjacent in
\(H[B]\). Thus they form a walk from \(\alpha\) to \(\beta\).

Let \(C\) be the connected component of \(H[B]\) containing \(I_T\).
Every vertex of \(T\) lies in \(S_\alpha\) for some
\(\alpha\in I_T\), so \(T\subseteq S_C\). The final bound follows
from item 3.
\end{proof}

\subsection{Recoverability of small errors}

Set $m\coloneqq \left\lceil\frac{d}{r}\right\rceil$.
If every connected component of \(H[B]\) has fewer than \(m\)
locations, Lemma~\ref{lem:layered-geometry} implies that every
connected component \(T\) of \(\Gamma[S_B]\) satisfies
\begin{equation}
|T|\leq r(m-1)<d.    
\end{equation}

We first record the corresponding consequence for operators supported
on \(S_B\).

\begin{lemma}
\label{lem:app-scalar-compression}
Let \(R\) be a set of physical qubits such that every connected
component of \(\Gamma[R]\) has fewer than \(d\) vertices. For any
operators \(O_1,O_2\) supported on \(R\) and any syndrome
\(s\in\Sigma\), there is a scalar \(\lambda_s(O_1,O_2)\) such that
\begin{equation}
P_{\cC}O_2^\dagger\Pi_sO_1P_{\cC}
=
\lambda_s(O_1,O_2)P_{\cC}.
\label{eq:app-scalar-compression}
\end{equation}
\end{lemma}

\begin{proof}
Expand \(O_1\) and \(O_2\) in the Pauli basis. For a Pauli operator
\(E\), let \(s(E)\) denote its syndrome. Then
\[
\Pi_sEP_{\cC}
=
\begin{cases}
EP_{\cC}, & s(E)=s,\\
0, & s(E)\neq s.
\end{cases}
\]
Hence a term $P_{\cC}E_2^\dagger\Pi_sE_1P_{\cC}$
can be nonzero only if \(s(E_1)=s(E_2)=s\). For such a pair,
\(E_2^\dagger E_1\) has trivial syndrome and is supported on \(R\).
Every connected component of its support is contained in a connected
component of \(\Gamma[R]\), and therefore has fewer than \(d\)
vertices. By Lemma~1 of ~\cite{KovalevPryadko2013},
\begin{equation}
P_{\cC}E_2^\dagger E_1P_{\cC}
=
\lambda(E_1,E_2)P_{\cC}.    
\end{equation}

Summing over the Pauli expansions of \(O_1\) and \(O_2\) proves the
claim.
\end{proof}

We now apply Lemma~\ref{lem:app-scalar-compression} to the {error}
expansion. Recall that
\[
\Ad_U=\sum_{B\subseteq\Lambda}F_B.
\]
Let
\begin{equation}
\cT_{\mathrm{small}}
\coloneqq 
\sum_{\substack{B\subseteq\Lambda:\\
\text{every component of }H[B]\text{ has size }<m}}
F_B
\label{eq:app-small-map}
\end{equation}
denote the part of the expansion in which every connected component
has fewer than \(m\) locations.

Define the syndrome channel on the physical system by
\begin{equation}
\cQ_{\mathrm{syn}}(Y)
\coloneqq 
\sum_{s\in\Sigma}
\Tr(\Pi_sY)\ket{s}\!\bra{s}.
\label{eq:app-syndrome-channel}
\end{equation}
The complementary channel \(\cQ_U\) can be written as
\begin{equation}
\cQ_U
=
\cQ_{\mathrm{syn}}\circ\Ad_U\circ\Ad_V.
\label{eq:complementary-channel-factorization}
\end{equation}
Indeed,
\begin{equation}
\begin{aligned}
\cQ_{\mathrm{syn}}
\circ\Ad_U\circ\Ad_V(X)
&=
\sum_{s\in\Sigma}
\Tr\!\left(\Pi_sUVXV^\dagger U^\dagger\right)
\ket{s}\!\bra{s} \\
&=
\sum_{s\in\Sigma}
\Tr\!\left(K_s^\dagger K_sX\right)
\ket{s}\!\bra{s}
=
\cQ_U(X).
\end{aligned}
\end{equation}

\begin{lemma}
\label{lem:app-small-cancellation}
There is a diagonal operator \(\sigma_{\mathrm{small}}\) on the
syndrome register such that
\begin{equation}
\cQ_{\mathrm{syn}}
\circ\cT_{\mathrm{small}}
\circ\Ad_V(X)
=
\Tr(X)\sigma_{\mathrm{small}}.
\label{eq:app-small-trace-only}
\end{equation}
Consequently,
\begin{equation}
\cQ_{\mathrm{syn}}
\circ\cT_{\mathrm{small}}
\circ\Ad_V
\circ(\id-\cD_A)
=
0.
\label{eq:app-small-cancellation}
\end{equation}
\end{lemma}

\begin{proof}
For \(B\subseteq\Lambda\) and \(K\subseteq B\), let \(u_K\) denote
the product of the unitaries \(u_\alpha\), \(\alpha\in K\), in circuit
order, with \(u_\varnothing=I\). Expanding the {error} maps gives
\begin{equation}
F_B
=
\sum_{K\subseteq B}
(-1)^{|B|-|K|}\Ad_{u_K}.
\label{eq:explicit-FB}
\end{equation}

Consider a set \(B\) appearing in
Eq.~\eqref{eq:app-small-map}. Every connected component of
\(\Gamma[S_B]\) has fewer than \(d\) qubits. Since
\(\supp(u_K)\subseteq S_B\),
Lemma~\ref{lem:app-scalar-compression} gives
\[
V^\dagger u_K^\dagger\Pi_su_KV
=
\lambda_s(u_K,u_K)I_A
\]
for every \(s\in\Sigma\). Hence
\begin{align}
\cQ_{\mathrm{syn}}
\circ\Ad_{u_K}
\circ\Ad_V(X)
&=
\sum_{s\in\Sigma}
\Tr\!\left(
V^\dagger u_K^\dagger\Pi_su_KVX
\right)
\ket{s}\!\bra{s}
\nonumber\\
&=
\Tr(X)
\sum_{s\in\Sigma}
\lambda_s(u_K,u_K)\ket{s}\!\bra{s}.
\label{eq:app-small-unitary-term}
\end{align}
Substituting Eq.~\eqref{eq:explicit-FB} and summing over the sets
\(B\) in Eq.~\eqref{eq:app-small-map}, the coefficient of each
\(\ket{s}\!\bra{s}\) remains proportional to \(\Tr(X)\). This proves
Eq.~\eqref{eq:app-small-trace-only}.
Equation~\eqref{eq:app-small-cancellation} then follows from
Lemma~\ref{lem:input-independence}.
\end{proof}

Since
\[
\Ad_U-\cT_{\mathrm{small}}
=
\sum_{\substack{B\subseteq\Lambda:\\
H[B]\text{ has a component of size }\geq m}}
F_B,
\]
Eqs.~\eqref{eq:complementary-channel-factorization} and
\eqref{eq:app-small-cancellation} give
\begin{equation}
\begin{aligned}
\cQ_U\circ(\id-\cD_A)
&=
\cQ_{\mathrm{syn}}
\circ\Ad_U
\circ\Ad_V
\circ(\id-\cD_A) \\
&=
\cQ_{\mathrm{syn}}
\circ
\bigl(\Ad_U-\cT_{\mathrm{small}}\bigr)
\circ\Ad_V
\circ(\id-\cD_A).
\end{aligned}
\label{eq:large-component-reduction}
\end{equation}
Thus only {error} sets \(B\) for which \(H[B]\) contains a connected
component of at least \(m\) locations remain. The next appendix bounds
their total contribution.

\subsection{Bounding large cluster contributions}
\label{app:ordered-expansion}

Appendix~\ref{app:subdistance-cancellation} shows that only {error} configurations containing a large connected cluster can contribute to logical information leakage. We now bound their total contribution.

For a certain large connected cluster, there are exponentially many possible choices of {errors} elsewhere in the circuit. Bounding these choices separately would introduce an exponential dependence on the total number of circuit locations. We instead sum over all remaining {errors} before taking the norm.

We first record a bound on the strength of a single channel {error}.
\begin{lemma}
\label{lem:single-fault-norm}
If \(|\eta|\leq\pi/2\), then
\begin{equation}
\norm{F_\alpha}_\diamond
\leq
2\sin|\eta|.
\label{eq:appendix-sine}
\end{equation}
\end{lemma}

\begin{proof}
Since \(F_\alpha\) is the difference of two channels, the optimization
in its diamond norm may be restricted to pure joint input states. Let
\(\ket{\psi}_{PR}\) be a pure state of the physical system \(P\) and
an arbitrary reference system \(R\). Using the trace distance between
pure states, we obtain
\begin{align}
&\norm{
(F_\alpha\otimes\id_R)
\bigl(\ket{\psi}\!\bra{\psi}\bigr)
}_1
\nonumber\\
&\quad=
\norm{
(u_\alpha\otimes I_R)\ket{\psi}\!\bra{\psi}
(u_\alpha^\dagger\otimes I_R)
-
\ket{\psi}\!\bra{\psi}
}_1
\nonumber\\
&\quad=
2\sqrt{
1-
\left|
\bra{\psi}u_\alpha\otimes I_R\ket{\psi}
\right|^2
}.
\label{eq:pure-state-distance}
\end{align}

Let
\(\rho_P\coloneqq \Tr_R(\ket{\psi}\!\bra{\psi})\).
Since \(h_\alpha\) is Hermitian and
\(\norm{h_\alpha}\leq 1\), it has a spectral decomposition
\begin{equation}
h_\alpha
=
\sum_j\lambda_j\ket{j}\!\bra{j},
\qquad
\lambda_j\in[-1,1].
\label{eq:local-generator-spectrum}
\end{equation}
Writing
\(p_j\coloneqq \bra{j}\rho_P\ket{j}\), we have
\begin{equation}
\bra{\psi}u_\alpha\otimes I_R\ket{\psi}
=
\Tr(\rho_Pu_\alpha)
=
\sum_jp_je^{-\mathrm{i}\eta\lambda_j}.
\label{eq:local-unitary-overlap}
\end{equation}
For \(|\eta|\leq\pi/2\), Eq.~\eqref{eq:local-unitary-overlap}
satisfies
\begin{align}
\operatorname{Re}\Tr(\rho_Pu_\alpha)
=
\sum_jp_j\cos(\eta\lambda_j)
\nonumber\geq
\cos|\eta|,
\label{eq:local-unitary-real-part}
\end{align}
where we used \(|\lambda_j|\leq1\). Therefore,
\begin{equation}
\left|
\bra{\psi}u_\alpha\otimes I_R\ket{\psi}
\right|
\geq
\cos|\eta|.
\label{eq:local-unitary-overlap-bound}
\end{equation}
Substituting Eq.~\eqref{eq:local-unitary-overlap-bound} into
Eq.~\eqref{eq:pure-state-distance} gives
\begin{equation}
\norm{
(F_\alpha\otimes\id_R)
\bigl(\ket{\psi}\!\bra{\psi}\bigr)
}_1
\leq
2\sin|\eta|.
\label{eq:single-fault-state-bound}
\end{equation}
The bound is uniform over the pure input state and the reference
system. Hence
\begin{equation}
\norm{F_\alpha}_\diamond
\leq
2\sin|\eta|,
\end{equation}
as claimed.
\end{proof}

\subsection{Expansion over large clusters}
\label{app:cluster-resummation}

For \(B\subseteq\Lambda\), call a connected component of \(H[B]\)
large if it contains at least \(m\) locations, and let
\(\nu_m(B)\) denote the number of such components. For every
\(W\subseteq\Lambda\), define
\begin{equation}
\cT_W(t)
\coloneqq 
\sum_{B\subseteq W}
t^{\nu_m(B)}F_B,
\qquad
0\leq t\leq1,
\label{eq:app-interpolation}
\end{equation}
with the convention \(0^0=1\). 

For \(W=\Lambda\), the endpoints are
\begin{equation}
\cT_\Lambda(1)=\Ad_U,
\qquad
\cT_\Lambda(0)=\cT_{\mathrm{small}}.
\label{eq:app-interpolation-endpoints}
\end{equation}
Hence
\begin{equation}
\Ad_U-\cT_{\mathrm{small}}
=
\int_0^1\cT_\Lambda'(t)\,\mathrm{d}t.
\label{eq:app-interpolation-integral}
\end{equation}

We next derive a useful expression for the derivative
\(\cT_W'(t)\). For \(C\subseteq W\), let \(N_W[C]\) denote the
closed neighborhood of \(C\) in the induced graph \(H[W]\).

\begin{lemma}
\label{lem:cluster-identity}
For every \(W\subseteq\Lambda\) and \(0\leq t\leq1\),
\begin{equation}
\cT_W'(t)
=
\sum_{\substack{C\subseteq W:\\
H[C]\text{ connected},\ |C|\geq m}}
F_C\circ
\cT_{W\setminus N_W[C]}(t).
\label{eq:appendix-derivative}
\end{equation}
\end{lemma}

\begin{proof}
Differentiating Eq.~\eqref{eq:app-interpolation} gives
\begin{equation}
\cT_W'(t)
=
\sum_{B\subseteq W}
\;
\sum_{\substack{
C\text{ a connected component of }H[B]\\
|C|\geq m}}
t^{\nu_m(B)-1}F_B.
\label{eq:raw-derivative}
\end{equation}
Here the inner sum accounts for the factor \(\nu_m(B)\) produced by
differentiation.

For each pair \((B,C)\) in
Eq.~\eqref{eq:raw-derivative}, set \(R\coloneqq B\setminus C\). Since \(C\)
is a connected component of \(H[B]\),
\[
R\subseteq W\setminus N_W[C].
\]
Conversely, any connected \(C\subseteq W\) with \(|C|\geq m\),
together with any \(R\subseteq W\setminus N_W[C]\), gives
\(B=C\cup R\) with \(C\) as a large connected component of \(H[B]\).
Thus the sum could be indexed by \(C\) and \(R\).

There are no edges between \(C\) and \(R\), so the corresponding
{error} maps commute across the two sets. Moreover, removing \(C\)
removes exactly one large component. Hence
\begin{equation}
F_B=F_C\circ F_R,
\qquad
\nu_m(B)=1+\nu_m(R).
\label{eq:marked-factorization}
\end{equation}
Reindexing Eq.~\eqref{eq:raw-derivative} and summing first over \(R\)
now gives
\begin{align}
\cT_W'(t)
&=
\sum_{\substack{C\subseteq W:\\
H[C]\text{ connected},\ |C|\geq m}}
F_C\circ
\sum_{R\subseteq W\setminus N_W[C]}
t^{\nu_m(R)}F_R
\nonumber\\
&=
\sum_{\substack{C\subseteq W:\\
H[C]\text{ connected},\ |C|\geq m}}
F_C\circ
\cT_{W\setminus N_W[C]}(t),
\end{align}
which proves Eq.~\eqref{eq:appendix-derivative}.
\end{proof}

